import { describe, expect, it } from 'vitest';

import { isUuidV7, parsePublicId, toPublicId, uuidV7Timestamp } from './ids.js';

// Generated by Postgres 18's uuidv7(); its uuid_extract_timestamp() returned
// 2026-10-07 01:38:39.463+00 for this id.
const FROM_POSTGRES = '01a11403-3ee7-7bb3-90d9-f58f45343f61';

describe('messaging public ids', () => {
  const kinds = [
    'conversation',
    'message',
    'channel_account',
    'contact_identity',
    'webchat_widget',
    'sms_connection',
    'sms_attempt',
    'phone_number',
    'call',
    'call_leg',
  ] as const;

  it.each(kinds)('round-trips a %s and refuses every other messaging kind', (kind) => {
    const id = toPublicId(kind, FROM_POSTGRES);
    expect(parsePublicId(kind, id)).toBe(FROM_POSTGRES);
    for (const other of kinds) {
      if (other !== kind) expect(parsePublicId(other, id)).toBeUndefined();
    }
    expect(parsePublicId('contact', id)).toBeUndefined();
  });

  it('uses separate public ids even when the stored UUID is the same', () => {
    expect(new Set(kinds.map((kind) => toPublicId(kind, FROM_POSTGRES))).size).toBe(kinds.length);
  });
});

describe('AI settings public ids', () => {
  const kinds = ['ai_connection', 'ai_connection_test', 'ai_request'] as const;

  it.each(kinds)('round-trips a %s and refuses every other AI kind', (kind) => {
    const id = toPublicId(kind, FROM_POSTGRES);
    expect(parsePublicId(kind, id)).toBe(FROM_POSTGRES);
    for (const other of kinds) {
      if (other !== kind) expect(parsePublicId(other, id)).toBeUndefined();
    }
    expect(parsePublicId('api_key', id)).toBeUndefined();
  });

  it('starts each with its own prefix', () => {
    expect(kinds.map((kind) => toPublicId(kind, FROM_POSTGRES).split('_')[0])).toEqual([
      'aic',
      'aict',
      'aireq',
    ]);
  });
});

describe('assistant conversation public ids', () => {
  const kinds = ['assistant_thread', 'assistant_turn', 'assistant_message'] as const;

  it.each(kinds)('round-trips a %s and refuses the other two', (kind) => {
    const id = toPublicId(kind, FROM_POSTGRES);
    expect(parsePublicId(kind, id)).toBe(FROM_POSTGRES);
    for (const other of kinds) {
      if (other !== kind) expect(parsePublicId(other, id)).toBeUndefined();
    }
  });

  it('starts each with its own prefix', () => {
    expect(kinds.map((kind) => toPublicId(kind, FROM_POSTGRES).split('_')[0])).toEqual([
      'athr',
      'aturn',
      'amsg',
    ]);
  });
});

describe('AI proposal public ids', () => {
  it('tells a proposal from the request that asked for its draft', () => {
    const proposal = toPublicId('proposal', FROM_POSTGRES);
    const draft = toPublicId('draft_request', FROM_POSTGRES);
    expect(proposal.startsWith('prop_')).toBe(true);
    expect(draft.startsWith('drq_')).toBe(true);
    expect(parsePublicId('proposal', proposal)).toBe(FROM_POSTGRES);
    expect(parsePublicId('draft_request', draft)).toBe(FROM_POSTGRES);
    expect(parsePublicId('proposal', draft)).toBeUndefined();
    expect(parsePublicId('draft_request', proposal)).toBeUndefined();
    expect(parsePublicId('ai_request', proposal)).toBeUndefined();
  });
});

describe('form public ids', () => {
  it('tells a form from one of its submissions', () => {
    const form = toPublicId('form', FROM_POSTGRES);
    const submission = toPublicId('form_submission', FROM_POSTGRES);
    expect(form.startsWith('form_')).toBe(true);
    expect(submission.startsWith('fsub_')).toBe(true);
    expect(parsePublicId('form_submission', submission)).toBe(FROM_POSTGRES);
    expect(parsePublicId('form', submission)).toBeUndefined();
    expect(parsePublicId('form_submission', form)).toBeUndefined();
  });
});

describe('import public ids', () => {
  it('tells an import from the file it read and the contacts it made', () => {
    const run = toPublicId('import', FROM_POSTGRES);
    expect(run.startsWith('imp_')).toBe(true);
    expect(parsePublicId('import', run)).toBe(FROM_POSTGRES);
    expect(parsePublicId('file', run)).toBeUndefined();
    expect(parsePublicId('contact', run)).toBeUndefined();
    expect(parsePublicId('import', toPublicId('file', FROM_POSTGRES))).toBeUndefined();
  });
});

describe('isUuidV7', () => {
  it('accepts a UUIDv7 generated by Postgres', () => {
    expect(isUuidV7(FROM_POSTGRES)).toBe(true);
  });

  it('accepts uppercase hex digits', () => {
    expect(isUuidV7(FROM_POSTGRES.toUpperCase())).toBe(true);
  });

  it('rejects other UUID versions', () => {
    expect(isUuidV7('5f0c9e3a-8b1d-4c2e-9f3a-1b2c3d4e5f60')).toBe(false);
  });

  it('rejects the wrong variant', () => {
    expect(isUuidV7('01a11403-3ee7-7bb3-c0d9-f58f45343f61')).toBe(false);
  });

  it.each([
    '',
    'not-a-uuid',
    '01a114033ee77bb390d9f58f45343f61',
    '01a11403-3ee7-7bb3-90d9-f58f45343f6',
  ])('rejects %j', (value) => {
    expect(isUuidV7(value)).toBe(false);
  });
});

describe('uuidV7Timestamp', () => {
  it('reads the same moment Postgres does', () => {
    expect(uuidV7Timestamp(FROM_POSTGRES).toISOString()).toBe('2026-10-07T01:38:39.463Z');
  });

  it('refuses anything that is not a UUIDv7', () => {
    expect(() => uuidV7Timestamp('5f0c9e3a-8b1d-4c2e-9f3a-1b2c3d4e5f60')).toThrow(TypeError);
  });
});
